export function parsePositionIdFromEvent(data: SuiTransactionBlockResponse) {
  let posId
  let farmsPosId
  const openEvent: any = data.events?.find(event => event.type.includes('pool::OpenPositionEvent'))
  if (openEvent) {
    posId = openEvent.parsedJson.position as string
  }

  const depositEvent: any = data.events?.find(event => event.type.includes('pool::DepositEvent'))
  if (depositEvent) {
    farmsPosId = depositEvent.parsedJson.wrapped_position_id as string
  }

  return { posId, farmsPosId }
}
export const isHexColor = (color: string) => /^#([0-9A-Fa-f]{3}|[0-9A-Fa-f]{6})$/i.test(color)
export const isRgbColor = (color: string) => /^rgb\(\s*(\d{1,3})\s*,\s*(\d{1,3})\s*,\s*(\d{1,3})\s*\)$/.test(color)
export const isRgbaColor = (color: string) => /^rgba\(\s*(\d{1,3})\s*,\s*(\d{1,3})\s*,\s*(\d{1,3})\s*,\s*(0(\.\d+)?|1(\.0+)?)\s*\)$/.test(color)
export const isColorValue = (color: string) => isHexColor(color) || isRgbColor(color) || isRgbaColor(color)

/**
 * 判断参数是否为非空对象
 * @param obj 需要判断的参数
 * @returns 如果参数是非空对象则返回 true，否则返回 false
 */
export const isAvailableObject = (obj: unknown): boolean => {
  // 首先判断是否为对象且不为 null
  if (obj === null || typeof obj !== 'object' || Array.isArray(obj)) {
    return false
  }

  // 判断对象是否为空（没有自有属性）
  return Object.keys(obj).length > 0
}

export const removeComma = (value: string) => {
  return (value + '')?.replace(/,/g, '')
}

export const formatTimestamp = (timestamp: string | number) => {
  const date = new Date(timestamp)

  const month = date.toLocaleString('en-US', { month: 'short', timeZone: 'UTC' }) // 获取 UTC 月
  const day = date.getUTCDate() // 获取 UTC 天
  const year = date.getUTCFullYear() // 获取 UTC 年

  let hours = date.getUTCHours() // 获取 UTC 小时
  const minutes = String(date.getUTCMinutes()).padStart(2, '0') // 获取 UTC 分钟

  const period = hours >= 12 ? 'PM' : 'AM'
  hours = hours % 12 || 12 // 0 变为 12，13 变为 1

  const formattedDate = `${month} ${day}, ${year} ${hours}:${minutes} ${period}`

  return formattedDate
}

export function base64ToUint8Array(base64: string): Uint8Array {
  const binaryString = Buffer.from(base64, 'base64').toString('binary')
  const uint8Array = new Uint8Array(binaryString.length)
  for (let i = 0; i < binaryString.length; i++) {
    uint8Array[i] = binaryString.charCodeAt(i)
  }
  return uint8Array
}

export const coinTypeIsequal = (coinTypeA: string, coinTypeB: string) => {
  return extractStructTagFromType(coinTypeA).full_address === extractStructTagFromType(coinTypeB).full_address
}

export function countLeadingZeros(str: string) {
  const match = str.match(/^0+/)
  return match ? match[0].length : 0
}

export const getPriceUnit = (price: string) => {
  const arr = price.split('.')
  if (d(arr?.[0]).gt(100000)) {
    return 0
  } else if (d(arr?.[0]).gt(0)) {
    return 4
  } else {
    const zero = countLeadingZeros(arr?.[1] || '')
    return zero + 4
  }
}

