import { create, StateCreator } from 'zustand'

interface cryptoState {
  currentCrypto: string
  setCurrentCrypto: (currentCrypto: string) => void

  isShowAlchemyCrypto: boolean
  setIsShowAlchemyCrypto: (isShowAlchemyCrypto: boolean) => void

  isShowKodoCrypto: boolean
  setIsShowKodoCrypto: (isShowKodoCrypto: boolean) => void
}

const store: StateCreator<cryptoState> = (set, get) => ({
  currentCrypto: '',
  setCurrentCrypto: (currentCrypto: string) => {
    set(() => ({
      currentCrypto
    }))
  },
  isShowAlchemyCrypto: false,
  setIsShowAlchemyCrypto: (isShowAlchemyCrypto: boolean) => {
    set(() => ({
      isShowAlchemyCrypto
    }))
  },
  isShowKodoCrypto: false,
  setIsShowKodoCrypto: (isShowKodoCrypto: boolean) => {
    set(() => ({
      isShowKodoCrypto
    }))
  }
})

const useCryptoStore = create(store)
export default useCryptoStore
