import localforage from 'localforage'

export class LocalForageService {
  protected storage: LocalForage

  constructor(name: string, storeName: string) {
    this.storage = localforage.createInstance({
      name,
      storeName
    })
  }

  // 设置数据
  async setItem<T>(key: string, value: T): Promise<void> {
    try {
      await this.storage.setItem(key, value)
    } catch (error) {
      console.error(`Failed to set item with key "${key}"`, error)
    }
  }

  // 获取数据
  async getItem<T>(key: string): Promise<T | null> {
    try {
      return await this.storage.getItem<T>(key)
    } catch (error) {
      console.error(`Failed to get item with key "${key}"`, error)
      return null
    }
  }

  // 获取所有数据
  async getAllItems<T>(): Promise<Map<string, T> | null> {
    try {
      const result = new Map<string, T>()
      await this.storage.iterate((value, key) => {
        result.set(key, value as T)
      })
      return result
    } catch (error) {
      console.error('Failed to get all items', error)
      return null
    }
  }

  // 删除数据
  async removeItem(key: string): Promise<void> {
    try {
      await this.storage.removeItem(key)
    } catch (error) {
      console.error(`Failed to remove item with key "${key}"`, error)
    }
  }

  // 清空存储
  async clear(): Promise<void> {
    try {
      await this.storage.clear()
    } catch (error) {
      console.error('Failed to clear storage', error)
    }
  }
}
